WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), islands AS (SELECT id, device_code, reading_ts, temp_c, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, COUNT(CASE WHEN device_code = 'DV-03' THEN 1 END) AS dv_03_count, ROUND(SUM(temp_c) / NULLIF(COUNT(CASE WHEN device_code = 'DV-03' THEN 1 END), 0), 2) AS temp_c_per_dv_03, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, MIN(reading_ts) AS first_seen FROM islands GROUP BY DATE_TRUNC('HOUR', reading_ts) ORDER BY hour_window NULLS FIRST
